from lib import *
S = SS('w57')
steps = [
    step("先排除一个常见误解:对端进程被 kill -9,不等于“对端消失”。服务端是另一个进程,建立连接并正常通信后(收到 pong)被 SIGKILL:线上立刻出现服务端→客户端的 FIN+ACK 和客户端→服务端的 ACK,客户端 recv 返回空字节串(有序关闭)。进程死了,内核还在,连接由内核替它收尾,本端马上就知道。半开连接要的是整台机器(或连接状态)悄无声息地没了。", t=tl(S(1)), mark=lidx(S(1), 'SIGKILL 之后线上的包', 'FIN+ACK'), done=lidx(S(1), '先正常通信', '客户端 recv 返回'), kv=KV([['kill -9 对端进程', '内核发 FIN,本端立刻知道'], ['客户端 recv', '返回空(EOF)'], ['说明', '进程死 ≠ 主机消失']], ['kill -9 对端进程'])),
    step("SIGSTOP 冻住对端进程(不是消失):对端应用不读也不写,但对端内核仍在替它 ACK。客户端一直写,共写进 1400312 字节(1.34 MiB)后 send 返回 EWOULDBLOCK(客户端发送缓冲区和对端接收缓冲区都满了),这段时间线上服务端内核一直在回纯 ACK,共 33 个。所以“对端没反应”和“对端的连接坏了”是两回事:冻住的对端从线路上看和健康的对端没有差别,只是窗口最终会满。(这一次写进的字节数比之前某次运行多,说明缓冲区的自动调整让这个数字不固定,以最后一次运行为准。)", t=tl(S(2)), mark=lidx(S(2), '对端冻住后客户端一直写'), done=lidx(S(2), '对端冻住后客户端一直写'), kv=KV([['对端冻住', '内核仍回 ACK'], ['客户端能写进', '约 1.34 MiB 后阻塞'], ['线路上', '看起来对端是活的']], ['客户端能写进'])),
    step("对照:对端用 SO_LINGER(1, 0) 关闭连接,close 时不走四次挥手,直接发 RST+ACK(线上只有这一个包,+0.000 s)。客户端随后的 send 报 Broken pipe(EPIPE),第二次也是 EPIPE。这是“被通知”的正常样子:对端明确告诉你连接没了。半开连接就是这个通知没到达的情形。", t=tl(S(3)), mark=lidx(S(3), 'RST+ACK', '客户端 send 报错'), done=lidx(S(3), '第二次 send 报错'), kv=KV([['对端 SO_LINGER(1,0)', '立刻发 RST+ACK'], ['客户端 send', 'EPIPE(Broken pipe)'], ['结果', '本端立刻知道']], ['对端 SO_LINGER(1,0)'])),
    step("制造真正的半开:lo0 上 netlab 每个方向丢 50%,40 个连接各在丢包环境下让服务端 SO_LINGER(1,0) 关闭(RST 有一半概率被丢)。0.5 秒后用 MSG_PEEK 探一下:22 个连接的客户端已被通知(ECONNRESET 或 EOF),18 个毫无察觉——服务端已经没有这条连接了,客户端还是 ESTABLISHED,这就是半开。再对这 18 个各发一次数据:服务端没有这个连接,会回 RST(这个 RST 同样有 50% 会被丢):14 个收到 ECONNRESET,4 个到这一刻仍无察觉。可见半开的连接不会自己恢复,只有本端“发数据去问”才会知道,而且一次不一定够。", t=tl(S(4)), mark=lidx(S(4), '毫无察觉的半开', '对这些半开连接'), done=lidx(S(4), '40 个连接里'), b=bars([['已被通知', 22, '22'], ['半开(无察觉)', 18, '18'], ['发数据后得到 ECONNRESET', 14, '14'], ['发数据后仍无察觉', 4, '4']], 40, mark=[1], done=[0, 2, 3]), kv=KV([['40 个连接', '22 个被通知,18 个半开'], ['对半开连接发数据', '14 个得到 RST,4 个仍无察觉'], ['注意', '丢包 50% 是制造半开的手段']], ['40 个连接'])),
    step("没有 keepalive、也没有数据时,半开连接不会自己结束。本端知道的两种时机都需要“动手”:发数据(对端丢了状态则回 RST;对端是黑洞则重传直到超时)或 keepalive 探测(上一篇)。黑洞的实测只做了建立连接这一种:向 example.com:81(丢 SYN)connect,75.0 秒后失败,ETIMEDOUT,正好等于本机 net.inet.tcp.keepinit = 75000 毫秒;另一个相关参数 msl = 15000 毫秒。已建立连接遇到黑洞后重传多久放弃,这篇没有测。", t=tl(S(5)), mark=lidx(S(5), 'connect 到 example.com:81'), done=lidx(S(5), '系统参数'), b=bars([['connect 到黑洞', 75.0, '75.0 s']], 75, mark=[0], done=[]), kv=KV([['connect 黑洞', '75.0 秒 ETIMEDOUT'], ['keepinit', '75000 毫秒'], ['已建立连接的黑洞', '本篇没测']], ['connect 黑洞'])),
]
A = mkartw('w57', 57, '网络协议,TCP,半开连接,RST,SO_LINGER,keepalive,真实验证,动画演示',
    '实测半开连接:进程被 kill -9 内核会发 FIN,本端立刻知道;SO_LINGER(1,0) 发 RST;在 50% 丢包下关闭 40 个连接,18 个客户端毫无察觉成为半开,发数据后 14 个收到 ECONNRESET;connect 到黑洞 75.0 秒后 ETIMEDOUT。',
    '“对端挂了,我什么时候才知道?”取决于怎么挂的:进程崩溃、主机断电、网线被拔,线路上留下的痕迹完全不同。这篇用 kill -9、SIGSTOP、SO_LINGER 0 和丢包注入逐种实测,看哪些情形本端立刻知道,哪些会形成半开连接。',
    [('18 / 40', '在 50% 丢包下关闭服务端时,RST 丢失、客户端毫无察觉的半开连接个数'), ('FIN+ACK', 'kill -9 对端进程后线上出现的包:内核替进程收尾'), ('75.0 s', 'connect 到丢 SYN 的黑洞后失败的时间')],
    [('进程死 ≠ 主机消失', '<p>对端进程被 kill -9,内核发 FIN,本端立刻读到 EOF。真正悄无声息的是整台机器或连接状态消失。</p>'),
     ('冻住的对端', '<p>SIGSTOP 的进程内核仍然 ACK,线路上看不出异常,只是窗口最终会满。</p>'),
     ('明确的通知', '<p>对端用 SO_LINGER(1,0) 关闭会发 RST,本端下一次 send 就是 EPIPE。</p>'),
     ('半开', '<p>RST 在路上丢了,本端还是 ESTABLISHED。只有本端发数据去问,对端才会回 RST;这个 RST 也可能再丢。</p>'),
     ('黑洞的等待', '<p>connect 到黑洞 75.0 秒才超时,等于 keepinit。已建立连接遇黑洞要等多久,本篇没有测。</p>')],
    steps,
    [ENV_W + '。第一至三节在 lo0 上;第四节用 netlab 丢包 50% 制造 RST 丢失(丢包上限 50%),是模拟;第五节对 example.com:81;第二节写进字节数每次运行不同,以最后一次为准',
     '没有验证:主机断电、拔网线后已建立连接的重传超时(黑洞下的 tcp_maxrtx 等);对端重启后收到老连接数据的真实 RST(用 SO_LINGER 模拟的);半开连接上 keepalive 发现的时间(上一篇用丢包代替);NAT 表项过期造成的半开;各种 TCP 栈(Linux)的差异'],
    '半开连接')
